# compute 8 directions segments
h,w=len(g),len(g[0]); pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==5]; o=[r[:] for r in g]
for i,(r,c) in enumerate(pts):
 for rr,cc in pts[i+1:]:
  dr,dc=rr-r,cc-c
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   n=max(abs(dr),abs(dc)); sr=0 if dr==0 else (1 if dr>0 else -1); sc=0 if dc==0 else (1 if dc>0 else -1)
   for k in range(1,n): o[r+k*sr][c+k*sc]=3
o

# unrestricted slope between points, use exact lattice steps
h,w=len(g),len(g[0]); pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==5]; import math
o=[r[:] for r in g]
for i,(r,c) in enumerate(pts):
 for rr,cc in pts[i+1:]:
  dr,dc=rr-r,cc-c; n=math.gcd(abs(dr),abs(dc))
  if n:
   sr,sc=dr//n,dc//n
   for k in range(1,n): o[r+k*sr][c+k*sc]=3
o
